begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,aud,role,email) values('ba000000-0000-4000-8000-000000000001','authenticated','authenticated','billing-1@example.test');
insert into auth.users(id,aud,role,email) values('ba000000-0000-4000-8000-000000000002','authenticated','authenticated','billing-2@example.test');
insert into auth.users(id,aud,role,email) values('ba000000-0000-4000-8000-000000000003','authenticated','authenticated','billing-3@example.test');
insert into auth.users(id,aud,role,email) values('ba000000-0000-4000-8000-000000000004','authenticated','authenticated','billing-4@example.test');
insert into public.trainer_workspaces(id,owner_user_id,name,timezone) values('ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000001','Billing A','Asia/Almaty'),('ba000000-0000-4000-8000-000000000011','ba000000-0000-4000-8000-000000000002','Billing B','UTC');
insert into public.client_records(id,workspace_id,user_id,display_name) values('ba000000-0000-4000-8000-000000000020','ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000003','A'),('ba000000-0000-4000-8000-000000000021','ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000004','Peer'),('ba000000-0000-4000-8000-000000000022','ba000000-0000-4000-8000-000000000011',null,'Foreign');
insert into public.bookings(id,workspace_id,client_record_id,starts_at,ends_at,status) values('ba000000-0000-4000-8000-000000000030','ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000020','2026-10-03 21:30:00+00','2026-10-03 22:30:00+00','confirmed');
insert into public.bookings(id,workspace_id,client_record_id,starts_at,ends_at,status) values('ba000000-0000-4000-8000-000000000031','ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000020','2026-10-03 21:30:00+00','2026-10-03 22:30:00+00','confirmed');
insert into public.bookings(id,workspace_id,client_record_id,starts_at,ends_at,status) values('ba000000-0000-4000-8000-000000000032','ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000020','2026-10-03 21:30:00+00','2026-10-03 22:30:00+00','confirmed');
insert into public.bookings(id,workspace_id,client_record_id,starts_at,ends_at,status) values('ba000000-0000-4000-8000-000000000033','ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000020','2026-10-03 21:30:00+00','2026-10-03 22:30:00+00','confirmed');
insert into public.bookings(id,workspace_id,client_record_id,starts_at,ends_at,status) values('ba000000-0000-4000-8000-000000000034','ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000020','2026-10-03 21:30:00+00','2026-10-03 22:30:00+00','confirmed');
insert into public.bookings(id,workspace_id,client_record_id,starts_at,ends_at,status) values('ba000000-0000-4000-8000-000000000035','ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000020','2026-10-03 21:30:00+00','2026-10-03 22:30:00+00','confirmed');
insert into public.bookings(id,workspace_id,client_record_id,starts_at,ends_at,status) values('ba000000-0000-4000-8000-000000000036','ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000020','2026-10-03 21:30:00+00','2026-10-03 22:30:00+00','cancelled_by_client');
insert into public.bookings(id,workspace_id,client_record_id,starts_at,ends_at,status) values('ba000000-0000-4000-8000-000000000037','ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000021','2026-10-03 21:30:00+00','2026-10-03 22:30:00+00','confirmed');
insert into public.bookings(id,workspace_id,client_record_id,starts_at,ends_at,status) values('ba000000-0000-4000-8000-000000000038','ba000000-0000-4000-8000-000000000011','ba000000-0000-4000-8000-000000000022','2026-10-03 21:30:00+00','2026-10-03 22:30:00+00','confirmed');
select ok(not has_table_privilege('authenticated','public.client_purchases','INSERT'),'direct purchase insertion denied');
select ok(not has_table_privilege('authenticated','public.credit_entries','UPDATE'),'direct credit updates denied');
select ok(not has_column_privilege('authenticated','public.credit_entries','created_by','SELECT'),'ledger actors hidden');
select ok(not has_table_privilege('authenticated','private.billing_command_receipts','SELECT'),'receipts private');
select ok(not has_function_privilege('anon','public.mark_attended(uuid,integer,uuid,boolean,uuid)','EXECUTE'),'anonymous marking denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ba000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('test.purchase',(public.create_client_purchase('ba000000-0000-4000-8000-000000000020','Three',3,9223372036854775807,'ba000000-0000-4000-8000-000000000100','2026-10-04'))::text,true);
select is((public.create_client_purchase('ba000000-0000-4000-8000-000000000020','Three',3,9223372036854775807,'ba000000-0000-4000-8000-000000000100','2026-10-04')->>'replayed')::text,'true','purchase retries once');
select throws_ok($$select public.create_client_purchase('ba000000-0000-4000-8000-000000000020','Changed',3,100,'ba000000-0000-4000-8000-000000000100','2026-10-04')$$,'22023',null,'purchase retry payload mismatch');
select throws_ok($$select public.create_client_purchase('ba000000-0000-4000-8000-000000000022','Foreign',1,100,'ba000000-0000-4000-8000-000000000101')$$,'P0002',null,'foreign client purchase denied');
select set_config('test.expired',public.create_client_purchase('ba000000-0000-4000-8000-000000000020','Expired',10,100,'ba000000-0000-4000-8000-000000000120','2026-10-03')::text,true);
select throws_ok($$select public.mark_attended('ba000000-0000-4000-8000-000000000035',1,'ba000000-0000-4000-8000-000000000121',true,(current_setting('test.expired')::jsonb->>'purchase_id')::uuid)$$,'55000',null,'explicit expired purchase rejected by local scheduled date');
select throws_ok($$select public.mark_attended('ba000000-0000-4000-8000-000000000035',2,gen_random_uuid(),false)$$,'40001',null,'stale booking revision rejected');
select set_config('test.mark',(public.mark_attended('ba000000-0000-4000-8000-000000000030',1,'ba000000-0000-4000-8000-000000000102',true))::text,true);
select is((current_setting('test.mark')::jsonb->>'service_date')::text,'2026-10-04','service date uses workspace local date');
select is((current_setting('test.mark')::jsonb->>'charged')::text,'true','expiry day remains eligible');
select set_config('test.plain',(public.mark_attended('ba000000-0000-4000-8000-000000000031',1,'ba000000-0000-4000-8000-000000000103',false))::text,true);
select is((current_setting('test.plain')::jsonb->>'charged')::text,'false','presence requires explicit charge');
select set_config('test.bind',(public.bind_attendance_purchase((current_setting('test.plain')::jsonb->>'attendance_id')::uuid,1,1,'ba000000-0000-4000-8000-000000000104'))::text,true);
select is((current_setting('test.bind')::jsonb->>'charged')::text,'true','unbound attendance can consume later');
select throws_ok($$select public.bind_attendance_purchase((current_setting('test.plain')::jsonb->>'attendance_id')::uuid,2,1,'ba000000-0000-4000-8000-000000000105')$$,'55000',null,'attendance binds only once');
select set_config('test.undo',(public.undo_attendance((current_setting('test.mark')::jsonb->>'attendance_id')::uuid,1,1,'Correction','ba000000-0000-4000-8000-000000000106'))::text,true);
select is((current_setting('test.undo')::jsonb->>'status')::text,'undone','correction preserves undone attendance');
select set_config('test.remark',(public.mark_attended('ba000000-0000-4000-8000-000000000030',1,'ba000000-0000-4000-8000-000000000107',true))::text,true);
select is((current_setting('test.remark')::jsonb->>'cycle')::text,'2','new mark uses new cycle');
select is((public.mark_attended('ba000000-0000-4000-8000-000000000030',1,'ba000000-0000-4000-8000-000000000102',true)->>'revision')::text,'1','old mark replay preserves original revision');
select is((public.undo_attendance((current_setting('test.mark')::jsonb->>'attendance_id')::uuid,1,1,'Correction','ba000000-0000-4000-8000-000000000106')->>'replayed')::text,'true','old undo replay preserves receipt');
select set_config('test.last',(public.mark_attended('ba000000-0000-4000-8000-000000000032',1,'ba000000-0000-4000-8000-000000000108',true))::text,true);
select is((current_setting('test.last')::jsonb->>'charged')::text,'true','last available unit consumed');
select set_config('test.empty',(public.mark_attended('ba000000-0000-4000-8000-000000000033',1,'ba000000-0000-4000-8000-000000000109',true))::text,true);
select is((current_setting('test.empty')::jsonb->>'charged')::text,'false','no stock preserves unbound attendance');
select is((public.mark_no_show('ba000000-0000-4000-8000-000000000034',1,'ba000000-0000-4000-8000-000000000110')->>'charged')::text,'false','no-show does not automatically debit');
select throws_ok($$select public.charge_late_cancellation('ba000000-0000-4000-8000-000000000034',1,'','ba000000-0000-4000-8000-000000000111')$$,'22023',null,'penalty requires public reason');
select set_config('test.penalty_purchase',(public.create_client_purchase('ba000000-0000-4000-8000-000000000020','Penalty unit',1,100,'ba000000-0000-4000-8000-000000000112'))::text,true);
select is((public.charge_late_cancellation('ba000000-0000-4000-8000-000000000034',1,'No-show policy','ba000000-0000-4000-8000-000000000113')->>'charged')::text,'true','explicit no-show penalty consumes unit');
select throws_ok($$select public.charge_late_cancellation('ba000000-0000-4000-8000-000000000034',1,'No-show policy','ba000000-0000-4000-8000-000000000114')$$,'55000',null,'penalty cannot charge twice');
select throws_ok($$select public.charge_late_cancellation('ba000000-0000-4000-8000-000000000030',1,'Double charge',gen_random_uuid())$$,'55000',null,'active presence cannot receive an additional penalty');
select throws_ok($$select public.mark_attended('ba000000-0000-4000-8000-000000000034',1,'ba000000-0000-4000-8000-000000000115',true)$$,'55000',null,'active no-show cannot be overwritten');
select throws_ok($$select public.mark_attended('ba000000-0000-4000-8000-000000000036',1,'ba000000-0000-4000-8000-000000000116',true)$$,'55000',null,'cancelled booking cannot mark present');
select throws_ok($$select public.mark_attended('ba000000-0000-4000-8000-000000000038',1,'ba000000-0000-4000-8000-000000000117',true)$$,'P0002',null,'foreign booking unavailable');
reset role;
select is((select sum(units) from public.credit_entries where purchase_id=(current_setting('test.purchase')::jsonb->>'purchase_id')::uuid)::text,'0','cycle correction restores once and balance never negative');
select is((select count(*) from public.credit_entries where kind='restore')::text,'1','old undo replay does not restore new cycle');
select throws_ok($$update public.client_purchases set title='Rewrite'$$,'55000',null,'purchase terms immutable even for administrator');
select throws_ok($$delete from public.credit_entries$$,'55000',null,'ledger history cannot be deleted');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ba000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('test.undo_noshow',public.undo_attendance((select id from public.attendance_records where booking_id='ba000000-0000-4000-8000-000000000034'),1,1,'Correct no-show','ba000000-0000-4000-8000-000000000119')::text,true);
select is((current_setting('test.undo_noshow')::jsonb->>'status'),'undone','no-show correction restores explicit penalty');
select is((public.undo_attendance((select id from public.attendance_records where booking_id='ba000000-0000-4000-8000-000000000034'),1,1,'Correct no-show','ba000000-0000-4000-8000-000000000119')->>'replayed'),'true','no-show penalty restoration replays once');
select is((public.mark_no_show('ba000000-0000-4000-8000-000000000034',1,'ba000000-0000-4000-8000-000000000122')->>'cycle'),'2','corrected no-show can start new cycle');
select is((public.charge_late_cancellation('ba000000-0000-4000-8000-000000000034',1,'No-show policy','ba000000-0000-4000-8000-000000000113')->>'cycle'),'1','old penalty replay retains original cycle');
select is((public.charge_late_cancellation('ba000000-0000-4000-8000-000000000034',1,'Current cycle policy','ba000000-0000-4000-8000-000000000123')->>'cycle'),'2','fresh penalty charges corrected current cycle');
select throws_ok($$select public.charge_late_cancellation('ba000000-0000-4000-8000-000000000034',1,'Current cycle policy',gen_random_uuid())$$,'55000',null,'new cycle penalty still charges only once');
select set_config('request.jwt.claims','{"sub":"ba000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is((select count(id) from public.client_purchases)::text,'3','linked client reads own purchases');
select is((select count(id) from public.attendance_records)::text,'5','linked client reads own attendance');
select throws_ok($$select created_by from public.client_purchases$$,'42501',null,'purchase actor identity unavailable');
select throws_ok($$select public.mark_attended('ba000000-0000-4000-8000-000000000035',1,'ba000000-0000-4000-8000-000000000118',true)$$,'42501',null,'client cannot mark attendance');
select set_config('request.jwt.claims','{"sub":"ba000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select is((select count(id) from public.client_purchases)::text,'0','peer cannot see client purchases');
select is((select count(id) from public.attendance_records)::text,'0','peer cannot see client attendance');
select set_config('request.jwt.claims','{"sub":"ba000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(id) from public.credit_entries)::text,'0','foreign owner cannot see credits');
reset role;
select throws_ok($$insert into public.credit_entries(workspace_id,client_record_id,purchase_id,attendance_id,booking_id,cycle,kind,units,created_by) values('ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000020',(current_setting('test.purchase')::jsonb->>'purchase_id')::uuid,(current_setting('test.mark')::jsonb->>'attendance_id')::uuid,'ba000000-0000-4000-8000-000000000031',99,'consume',-1,'ba000000-0000-4000-8000-000000000001')$$,'23503',null,'credit cannot point at another attendance booking');
select throws_ok($$insert into public.credit_entries(workspace_id,client_record_id,purchase_id,attendance_id,booking_id,cycle,kind,units,created_by) values('ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000021',(current_setting('test.purchase')::jsonb->>'purchase_id')::uuid,(current_setting('test.mark')::jsonb->>'attendance_id')::uuid,'ba000000-0000-4000-8000-000000000030',99,'consume',-1,'ba000000-0000-4000-8000-000000000001')$$,'23503',null,'credit cannot charge a peer client purchase');
select throws_ok($$insert into public.credit_entries(workspace_id,client_record_id,purchase_id,attendance_id,booking_id,cycle,kind,units,created_by) values('ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000020',(current_setting('test.purchase')::jsonb->>'purchase_id')::uuid,(current_setting('test.mark')::jsonb->>'attendance_id')::uuid,'ba000000-0000-4000-8000-000000000030',null,'consume',-1,'ba000000-0000-4000-8000-000000000001')$$,'23514',null,'consume requires an explicit attendance cycle');
select throws_ok($$insert into public.credit_entries(workspace_id,client_record_id,purchase_id,booking_id,kind,units,reason,created_by) values('ba000000-0000-4000-8000-000000000010','ba000000-0000-4000-8000-000000000020',(current_setting('test.purchase')::jsonb->>'purchase_id')::uuid,'ba000000-0000-4000-8000-000000000036','charge_late_cancel',-1,null,'ba000000-0000-4000-8000-000000000001')$$,'23514',null,'penalty cannot bypass required reason with null');
select * from finish();
rollback;
